-- Synthetic evaluation only. Empty dedicated PostgreSQL database required.
-- Not an application migration; not rerunnable; no credentials or contact fields.
BEGIN;
CREATE SCHEMA evaluation_v1;
SET LOCAL search_path TO evaluation_v1;
CREATE TABLE tb_department (department_id BIGINT, department_name TEXT, PRIMARY KEY (department_id));
CREATE TABLE tb_user (user_id BIGINT, department_id BIGINT, user_name TEXT, PRIMARY KEY (user_id), FOREIGN KEY (department_id) REFERENCES tb_department (department_id));
CREATE TABLE tb_team (team_id BIGINT, department_id BIGINT, team_name TEXT, status_code TEXT, deleted_at TEXT, PRIMARY KEY (team_id), FOREIGN KEY (department_id) REFERENCES tb_department (department_id));
CREATE TABLE tb_worklog (worklog_id BIGINT, author_id BIGINT, team_id BIGINT, title TEXT, request_content TEXT, work_content TEXT, status_code TEXT, importance_code TEXT, actual_hours NUMERIC, instruction_date TEXT, due_date TEXT, completion_date TEXT, ai_summary TEXT, ai_summary_edited BOOLEAN, ai_processing_status TEXT, is_deleted BOOLEAN, created_at TEXT, updated_at TEXT, PRIMARY KEY (worklog_id), FOREIGN KEY (author_id) REFERENCES tb_user (user_id), FOREIGN KEY (team_id) REFERENCES tb_team (team_id));
CREATE TABLE tb_worklog_dependency (worklog_id BIGINT, depends_on_worklog_id BIGINT, created_at TEXT, PRIMARY KEY (worklog_id, depends_on_worklog_id), FOREIGN KEY (worklog_id) REFERENCES tb_worklog (worklog_id), FOREIGN KEY (depends_on_worklog_id) REFERENCES tb_worklog (worklog_id));
COMMIT;
